fun buildPinner(
    host: String = PROTON_HOST,
    pins: List<String> = loadFromClasspath()
): CertificatePinner {
    val builder = CertificatePinner.Builder()
    if (pins.isNotEmpty()) {
        builder.add(host, *pins.toTypedArray())
    }
    return builder.build()
}

